//! The family directory: where a member finds what its agent-file
//! family shares.
//!
//! A member's work-side config names the directory in
//! `[family] home`, relative to the config file's directory. The
//! directory's `family.md` is in the config carrier's format, toml
//! fences in markdown, and holds two tables:
//!
//! - `[resources]`: the paths every member shares, by name, among
//!   them `work-template`, the template's payload, which
//!   `agent-files diff` and `copy` fall back to.
//! - `[members]`: each member's name and its repo.
//!
//! Paths in `family.md` are relative to the family directory, not
//! to the member reading it, so one file serves every member.

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use crate::{common, config_md, toml_simple};

/// The family directory's configuration file.
pub const FAMILY_MD: &str = "family.md";

/// The key naming the family directory in a member's config.
pub const FAMILY_HOME: &str = "family.home";

/// The resource naming the template's payload, the directory
/// holding the pinned agent-files.
pub const WORK_TEMPLATE: &str = "work-template";

/// A loaded family: the directory, as the member's config wrote it
/// and resolved, and `family.md`'s flat key map.
pub struct Family {
    home: String,
    dir: PathBuf,
    map: HashMap<String, String>,
}

/// A resource's path, resolved for use, and shown relative to the
/// member's config directory for a report.
#[derive(Debug, PartialEq, Eq)]
pub struct Resource {
    pub path: PathBuf,
    pub shown: String,
}

impl Family {
    /// The family of the workspace whose config is in `root`.
    ///
    /// `Ok(None)` when there is no config or it names no
    /// `family.home`. A home without a `family.md` is an error, as
    /// is a `family.md` that does not parse.
    pub fn load(root: &Path) -> Result<Option<Family>, Box<dyn std::error::Error>> {
        let Some(cfg) = config_md::load(root)? else {
            return Ok(None);
        };
        let Some(home) = toml_simple::toml_get(&cfg.map, FAMILY_HOME) else {
            return Ok(None);
        };
        let dir = common::resolve_repo_path(root, home);
        let path = dir.join(FAMILY_MD);
        if !path.is_file() {
            return Err(format!(
                "{FAMILY_HOME} '{home}': no {FAMILY_MD} in '{}'",
                dir.display()
            )
            .into());
        }
        let map = config_md::load_file(&path)?;
        Ok(Some(Family {
            home: home.clone(),
            dir,
            map,
        }))
    }

    /// The `[resources]` entry `name`, `None` when the family has
    /// none.
    ///
    /// - `path` is the value resolved against the family directory.
    /// - `shown` is the same place written from the member's config
    ///   directory and normalized, `family/../../x` read as `../x`,
    ///   so a report names it as the member would.
    pub fn resource(&self, name: &str) -> Option<Resource> {
        let value = toml_simple::toml_get(&self.map, &format!("resources.{name}"))?;
        let shown = common::normalize_path(&Path::new(&self.home).join(value));
        Some(Resource {
            path: common::resolve_repo_path(&self.dir, value),
            shown: shown.display().to_string(),
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A workspace root holding `config`, and `family.md` content in
    /// its `fam/` directory when given.
    fn workspace(tag: &str, config: Option<&str>, family_md: Option<&str>) -> PathBuf {
        let root = crate::test_tmp_root::resolve_tmp_root().join(format!("vc_x1_family_{tag}"));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("fam")).expect("mkdir");
        if let Some(c) = config {
            std::fs::write(root.join(config_md::VC_CONFIG_MD), c).expect("write config");
        }
        if let Some(f) = family_md {
            std::fs::write(root.join("fam").join(FAMILY_MD), f).expect("write family.md");
        }
        root
    }

    const CONFIG: &str = "```toml\n[family]\nmember = \"x\"\nhome = \"fam\"\n```\n";

    /// A resource resolves against the family directory, and is shown
    /// from the member's config directory, normalized.
    #[test]
    fn resource_resolves_against_the_family_directory() {
        let root = workspace(
            "resource",
            Some(CONFIG),
            Some("# f\n\n```toml\n[resources]\nwork-template = \"../tpl/work\"\n```\n"),
        );
        // OK: the fixture writes both files, so the family loads.
        let f = Family::load(&root).unwrap().expect("a family");
        let r = f.resource(WORK_TEMPLATE).expect("work-template");
        assert_eq!(r.path, root.join("fam").join("../tpl/work"));
        assert_eq!(r.shown, "tpl/work");
        assert_eq!(f.resource("messages"), None);
    }

    /// No config, or a config naming no home, is no family.
    #[test]
    fn no_home_is_no_family() {
        let root = workspace("no-config", None, None);
        // OK: a missing config is Ok(None), never an error.
        assert!(Family::load(&root).unwrap().is_none());
        let root = workspace("no-home", Some("```toml\n[family]\nmember = \"x\"\n```\n"), None);
        // OK: a config without family.home is Ok(None).
        assert!(Family::load(&root).unwrap().is_none());
    }

    /// A home without a family.md is an error naming both.
    #[test]
    fn a_home_without_family_md_errors() {
        let root = workspace("missing", Some(CONFIG), None);
        let err = Family::load(&root).err().expect("an error");
        let msg = err.to_string();
        assert!(msg.contains(FAMILY_HOME) && msg.contains(FAMILY_MD), "{msg}");
    }
}

